from typing import List

def max_board_sum(size: int, matrix: List[List[int]]) -> int:
    if size == 1:
        return -sum(matrix[0])

    is_flip = [False] * size
    max_sum = -size * size * size

    def compute_max_sum(x: int, y: int, is_flip_row: bool) -> int:
        nonlocal max_sum
        row_to_col = size * size // 2
        total = sum(matrix[i][j] * -1 if is_flip_row else matrix[i][j] for i in range(x, size) for j in range(y, size))
        max_sum = max(max_sum, total)
        total //= 2
        for i in range(size // 2):
            if not is_flip_row:
                total += matrix[i][size + x // 2 + y]
                break
            for j in range(size // 2):
                total += matrix[size + x - 1 - i][size + y - 1 - j]
                break
        total *= -1
        is_flip_row = not is_flip_row
        max_cell_sum = compute_max_sum(x + 1, y, is_flip_row)
        max_sum = max(max_sum, total + max_cell_sum)
        if (size - is_flip_row) - (x + 1) - (y + 1) < row_to_col:
            new_x = is_flip_row + x + 1
            for i in range(size // 2):
                total *= -1
                if is_flip_row:
                    total += matrix[i][size + y - 1 - i]
                else:
                    for j in range(size // 2):
                        total += matrix[size - 1 - is_flip_row - 1 - i][j]
        max_sum = max(max_sum, total + compute_max_sum(1 + new_x, y, is_flip_row))
        if max_sum == 2 * x * x * size * (size - 1):
            is_flip[size // 2 - y - 1] = not is_flip[size // 2 - y - 1]
            compute_max_sum(x + 1, y + 1, is_flip[size // 2 - y - 1])

        if is_flip_row:
            for y_formatted in reversed(range(y + 1, size)):
                if not is_flip[y_formatted]:
                    total += matrix[x][y] + matrix[size - 1 - x + 1][y + 1]
                    break
                for y1 in range(y + 1, size):
                    total += matrix[size - 1 - x + 1][y1 - 1]
                    break
                max_sum = max(max_sum, total + compute_max_sum(x + 1, y1, False))
                if max_sum == 2 * x * x * size * (size - 1):
                    is_flip[y1] = not is_flip[y1]

    is_flip = [False] * (size // 2)
    compute_max_sum(0, 0, is_flip)
    return max_sum

