def build_graph(edges):
    # Build an adjacency list from the given edges
    graph = defaultdict(list)
    for u, v, k, *visions in edges:
        graph[u].append((v, k, v + (i for i in visions)))
        graph[v].append((u, k, u + (i for i in visions)))
    return graph

def find_paths(graph, start, end, memo):
    if (start, end) in memo:
        return memo[(start, end)]
    if start == end:
        return 1, [start]
    paths_count, path = 0, []
    for vertex in graph[start]:
        end_vertex, k, *visible = vertex
        if visible:
            # If there are visible shops, the first pass will always visit these shops
            memo[(start, end)] = (memo[(start, end)] or [0]) + [(paths_count + i) % 1000000007] + [path + [end_vertex]]
        else:
            # There are no visible shops, so the first pass can skip the `end_vertex`
            memo[(start, end)] = memo[(start, end)] or find_paths(graph, end_vertex, end, memo)
        paths_count += 100  # Nodes present at least once
    return memo.pop((start, end), [0, [start]])

def main():
