from collections import deque

def simulate_event(events):
    global rows, cols
    rows, cols = sorted(events[0:rows + 1])  # top to bottom
    stack = deque()
    visited = set()

    for row in events[rows + 1:]:
        start, end, direction = [int(num) for num in row.split()]

        # Check if top or bottom of table is reached
        bottom = stack[-1] if stack else (-1, -1)
        if start == bottom:
            if direction == ">":  # reach the bottom, stay there
                continue
            elif direction == "<":  # tap at the bottom: infinite loop detected..
                return "Not possible"
            else:
                return top_to_end_reverse(stack, empty_to_fill(start, direction), start, end)
        elif end == bottom:
            return top_to_end(stack, start, end)

        cur_seat_to_fill = top_to_end_recurse(stack, start, end, direction)
        predecessor, (cur_row, cur_col) = cur_seat_to_fill

        stack.append((cur_row, cur_col))

        new_direction = get_new_direction(bottom, cur_seat_to_fill)
        visited.add((cur_row, cur_col))

        stack, all_seats, stack.clear() = stack_stack_update(
            stack, all_seats, predecessor, bottom, new_direction, cur_seat_to_fill)

def top_to_end(stack, start, end):
    if len(stack) == 0 or stack[0][0] > end:
        if start > end:
            return stack, (stack[0][0], stack[0][1])
        else:
            return stack, (end, start)
    else:
        return top_to_end(stack, stack[0][0], min(end, start))

def top_to_end_reverse(stack, cur_row, end):
    if len(stack) == 0 or stack[-1][0] > end:
        if end > cur_row:
            return stack, (stack[-1][0], stack[-1][1])
        else:
            return stack, (end, cur_row)
    else:
        return top_to_end_reverse(
            stack[::-1], max(cur_row, start), end)

def get_new_direction(stack_top, cur_seat_to_fill):
    right_stack = stack[stack_top][1] < cur_seat_to_fill[1]
    bottom_stack = stack_top < len(stack) - 1
    repeat_head = stack[stack_top][0] == bottom_stack and stack[stack_top][1] == cur_seat_to_fill[1]
    left_stop = prev_seat_to_end_recurse(prev, cur_seat_to_fill) != cur_seat_to_fill 

    if left_stop or repeat_head or bottom_stack:  # infinite loop detected by backtrack base criteria
        return "<"
    elif bottom_stack and cur_seat_to_fill[1] > prev_seat_to_end_recurse(prev)[0]:
        return "^"
    else:
        return ">" if cur_seat_to_fill[1] >= stack[stack_top][1] else "<"

ascending_directions = {"<": ">", "^": ">"}
descending_directions = {">": "<", "^": "<"}

def top_to_end_recurse(stack, start, end, direction):
    if start > end:
        return (stack[0][0], stack[0][1])
    else:
        return max(
            top_to_end_recurse(stack, start, max(end, prev_seat_to_end_recurse(prev)) if repeat_head else end + 1, (direction == "<") and descending_directions[direction]), 
