from functools import lru_cache, lru_cache

def shortest_path(graph, start):
    if start not in graph:
        return 0

    queue = deque([(start, 0)])

    memo = {start: 1}
    while len(queue):
        vertex, cost = queue.popleft()

        for neighbor, weight in graph[vertex].items():
            if cost + 1 in memo:
                memo[neighbor] = (memo[neighbor] + memo[vertex]) % 1000000007
            else:
                memo[neighbor] = memo[vertex] if neighbor == start else 0
                queue.append((neighbor, cost + 1))

    min_cost = min(cost for vertex in memo if cost > 0)
    return memo[1], memo[2] if min_cost else 0

def find_paths(graph, start, stop, p, p_count):
    if start == stop:
        if itinerary[p_count] == stop:
            return 1, itinerary[p_count]
        return 0, tuple(itinerary[:p_count])

    count = 0
    copy = ['-'] * len(p + 1)
    for i in range(len(p)):
        copy[p[i]] = stop
    for neighbor, weight in graph[start].items():
        itinerary_length, itinerary = find_paths(graph, neighbor, stop, p, p_count + 1)
        if itinerary_length:
            itinerary_count = 0
            for i in range(len(itinerary) - 1):
                if copy[itinerary[i]] == itinerary[i + 1]:
                    itinerary_count += 1
            if itinerary_count <= weight + count:
                copy[p[p_count % len(p)]] = start
                count += 1
                copy[p[p_count % len(p) + 1]] = stop
                return count, tuple(copy)

    return 0, tuple(copy)

def main():
    n, m = map(int, input().split())
    graph = defaultdict(dict)
    counter = 1
    for _ in range(m):
        x, y, w, *wall = list(map(int, input().split()))
        if wall:
            for vertex in wall:
                graph[x][counter] = graph[counter][x] = counter
                graph[counter][y] = graph[y][counter] = counter
                counter += 1
            for vertex in wall:
                if y not in graph[x]:
                    graph[x][y] = counter
                if x not in graph[y]:
                    graph[y][x] = counter
                counter += 1
        else:
            graph[x][counter] = graph[counter][x] = counter
            graph[counter][y] = graph[y][counter] = counter
            counter += 1

    p_count = shortest_path(graph, 1)[1]
    _, corridor = find_paths(graph, 1, p_count, [0] * (2 * p_count), 0)

    if corridor[0]:
        corridor.pop()
    return f"{len(corridor) + p_count}\n" + "\n".join(map(str, corridor))

