from collections import deque, defaultdict

def build_graph(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)
    return graph

def dijkstra(graph, src, dest):
    distance = {node: float('inf') for node in range(n)}
    distance[src] = 0
    queue = deque([(0, src)])
    while queue:
        current_distance, current_node = queue.popleft()
        if current_distance > distance[current_node]:
            continue
        for neighbor in graph[current_node]:
            distance[neighbor] = min(distance[neighbor], current_distance + 1)
            queue.append((distance[neighbor], neighbor))
    path = []
    current = dest
    while current != src:
        for neighbor in graph[current]:
            if distance[neighbor] == distance[current] - 1:
                path.append((current, neighbor))
                current = neighbor
                break
    path.append((src, dest))
    return path

def main():
