from collections import deque

def find_min_balls_not_getting_present(n, k, permutation):
    graph = [[] for _ in range(n)]
    in_degree = [0] * n
    for i in range(n):
        graph[i].append(permutation[i] - 1)
        in_degree[permutation[i] - 1] += 1

    min_kids = [0] * n

    def bfs():
        queue = deque()
        for i in range(n):
            if not in_degree[i]:
                queue.append(i)
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if not in_degree[neighbor]:
                    queue.append(neighbor)
                min_kids[min_kids[neighbor]] = max(min_kids[min_kids[neighbor]], min_kids[node] + 1)

    bfs()

    min_balls = 0
    max_balls = 0
    for kid in min_kids:
        min_balls += kid
        for _ in range(1, k + 1):
            reached = False
            for adj in graph[min_kids[kid]]:
                if reached or adj not in min_kids:
                    continue
                min_kids[min_kids[adj]] = max(kid + 1, min_kids[adj])
                min_balls += min_kids[adj] if reached else 0
                reached = True

    return min_balls, min_balls + k

