```python
import heapq

def bfs(grid, start, end):
    n, m = len(grid), len(grid[0])
    visited = [[False for _ in range(m + 2)] for _ in range(n + 2)]
    queue = [[start[0], start[1], 0, -1]]
    while queue:
        x, y, d, cur = heapq.heappop(queue)
        if d > 10**6:
            return -1
        if x == end[0] and y == end[1]:
            return d
        if visited[x][y]:
            continue
        visited[x][y] = True
        for dx, dy in [(-1, 0), (0, -1), (1, 0), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n + 2 and 0 <= ny < m + 2 and grid[nx][ny] not in ['<', '>', '^']:
                heapq.heappush(queue, [nx, ny, d + 1])
            if 0 <= nx < n + 2 and 0 <= ny < m + 2 and grid[nx][ny] in ['<', '>', '^']:
                if grid[nx][ny] == '<' and dx > 0:
                    heapq.heappush(queue, [nx + 1, ny, d + 1])
                elif grid[nx][ny] == '>' and dx < 0:
                    heapq.heappush(queue, [nx - 1, ny, d + 1])
                elif grid[nx][ny] == '^' and dy > 0:
                    heapq.heappush(queue, [nx, ny + 1, d + 1])
                elif grid[nx][ny] == '>' and dy < 0:
                    heapq.heappush(queue, [nx, ny - 1, d + 1])
    return -1

def solve(n, m, q, arr):
    grid = [['^' if i == j else grid[i-1][j-1] for j in range(m + 2)] for i in range(n + 2)]
    arr = [(query[0] - 1, query[1] - 1) if query[0] == 'A' else query[1] - 1 for query in arr]
    bfs(grid, arr[0], arr[0])
    for i in range(1, len(arr)):
        if bfs(grid[i], arr[i-1], arr[i]) == -1:
            return bfs(grid[0], arr[i-1], arr[i])
    return bfs(grid[i], arr[0], arr[1])

