from collections import Counter

def find_permutation(b, q):
    n = len(b)
    i = 0
    while i < n and b[i] == 0:
        i += 1

    max_inv = max(b)
    if max_inv == i - 1:
        return [i for j in range(1, i)]  # The only permutation that has no inversions
    else:
        first_inversion = -1
        last_inversion = -1
        for j in range(i, n):  
            if b[j] == i - 1:
                first_inversion = j
            elif b[j] == i:
                last_inversion = j
                continue
            elif b[j] == i:
                first_inversion = j

    result = [-1] * q
    for j in range(q):
        if b[j] == 0:
            if j % 2 == 0:
                result[j] = first_inversion + 1
            else:
                result[j] = last_inversion + 1
        elif b[j] == 1:
            x = b[j] + 1
            if j % 2 == 0:
                result[j] = first_inversion + 1
            else:
                result[j] = normal(first_inversion + 1, last_inversion + 1, x, n)
    return result

def normal(first, last, x, n):
    count = 0
    for j in range(2, n):
        if first <= j <= last or first <= n - j <= last:
            count += 1
    return min(x - count, n - x - count)

