from collections import Counter

def calculate_weight(s, indices):
    if len(indices) == 0:
        return 0, 0

    weights = Counter()
    for i in s:
        if i not in indices:
            if weights[i] > 0:
                weights[i] += 1
            else:
                weights[i] = 1
        else:
            if weights[i] == 0:
                weights[i] = 1
            else:
                weights[i] -= 1

