import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def creative_gcd(a, b):
    return int((a * b) // math.gcd(a, b))

def max_gcd_range_sum(arr, l, r):
    total_gcd = max(creative_gcd(arr[l-1], arr[r]), creative_gcd(arr[l-1], arr[l-2]) if l > 1 else 0)
    for i in range(l, r):
        total_gcd = max(total_gcd, creative_gcd(total_gcd, arr[i+1]))
    return total_gcd

def stone_game(stones, n, l):
    n1, n2 = l-1, l+1
    row1, row2 = [[] for _ in range(n)], []
    while n1+1 < n and stones[n1+1] == stones[n1] and stones[n2+1] == stones[n2]:
        n1, n2 = n1 + 3, max(n2+1, 0)
    for i in range(1, n + 1):
        row1[i] = stones[n1 + i]
        if n2 + i <= n:
            row2.append(stones[n2 + i])
    sn1, sn2 = n1 + 1, n2 + 1
    mn, mx = max_gcd_range_sum(row1, sn1, n1), max_gcd_range_sum(row2, sn2, n2)
    return max(mx, mx)

