import sys

def compute_permutation(b, n):
    # Compute number of inversions of size i in all previously observed permutations
    inversions = [0] * (n + 1)
    for i in range(1, n + 1):
        inversions[i - 1] = b[i - 1]
        for j in range(i):
            if b[j] < b[i]:
                inversions[i - 1] += 1

    # Majority-count permuations of available number of inversions
    permutations = [0] * (2 ** n + 1)
    max_permutations = [0] * (2 ** n + 1)
    s = 0
    for i in range(2 ** n, 0, -1):
        permutations[s - 1] = i
        inversions[s - 1] = 0
        count = bin(i).count('1')
        max_permutations[s - 1] = s
        if count:
            for j in range(count):
                inversions[s - 1] += 1
                s += 1
        s += 1

    for i in range(n + 1):
        if inversions[i] < len(max_permutations) and inversions[i] > 0:
            permutations[i - 1] = max_permutations[i]

    # Put i to the leftmost postion. Otherwise, pick the leftmost candidate
    i = 0
    while count := inversions[i] >= n // 2:
        i += 1
    return permutations[i]

