        lines[col] += get_min_num(k, x2 - x1) - get_min_num(k - 1, x2 - x1) + 1

    for i in range(x1, x2):
        need = 0
        for col, value in sorted(lines.items(), key=lambda x:x[0], reverse=True):
            if need > k:
                break
            need += value
            lines[col] -= value

        for col, value in lines.items():
            answers[col] += (i - x1) * value + ans
            ans += value

        if k > 0:
            answers[col] += k * (i - x1 + 1)
            k -= 1

