import sys

@lru_cache(maxsize=None)
def dynamic_programming(length, last, prefix, t):
    if length == 0:
        return 0
    if length == 1:
        if t[length - 1] == '1':
            return 1
        else:
            return 0
    choices = [0] * 26
    for i in range(length - 2, -1, -1):
        if t[length - 1] == '0':
            # The following character is allowed to be part of the answer
            if last != -1 and last != length - 1:
                choices[prefix[length - 1] - ord('a')] += dynamic_programming(i, length - 1, -1, t)
            else:
                choices[prefix[length - 1] - ord('a')] += 1
        else:
            # The following character is only allowed if it comes after a forbidden index
            if length - 1 - i > prefix[length - 1] - ord('a'):
                choices[prefix[length - 1] - ord('a')] += dynamic_programming(i, length - 1, length - 1, t)
            else:
                choices[prefix[length - 1] - ord('a')] += dynamic_programming(i, length - 1, -1, t)
    return max(choices)

@lru_cache(maxsize=None)
def longest_unallowed(candidates, valid_prefixes, window_length, banned_indices):
    banned_prefixes, prefix_score = valid_prefixes
    B = ['9' for _ in range(window_length)]
    if candidates:
        a = candidates[0]
        partial_score = prefix_score[a - ord('a')]
        if a not in banned_indices and partial_score < window_length:
            partial_score += 1
            a += 1
    else:
        return 0

    if a < len(banned_prefixes) and a not in banned_indices:
        current_score = B[a] + partial_score
        if current_score > 9 and B[a] != '9':
            for i in range(a + 1, len(banned_prefixes)):
                D = list(B)
                D[i] = a + 1
                possibles = [
                    t.replace(c, '.')
                    for t in prefix_score
                    for c in candidates
                    if i <= c <= a + window_length
                ]
                current_score += max(longest_unallowed(possibles, (banned_prefixes, prefix_score), window_length, banned_indices), 0)
