import sys
import math

def max_sum(n, board):
    mod = 10**9 + 7
    inverse_map = [0] * n
    inverse_map[n//2] = 1
    prefix = bytearray(fill=2 ** (n.bit_length()))
    overflow = bytearray(swap=True)

    for row in range(n):
        rev(row, 0, prefix, overflow)
        apply_row(row, board[:, row].bytes)
        row = mask(row, n-1, inverse_map)
        reverse(row, 0, prefix, overflow)

        for column in range(n):
            rev(column, 0, prefix, overflow)
            apply_col(column, board[row, :].bytes)
            column = mask(column, n-1, inverse_map)
            reverse(column, 0, prefix, overflow)

    rev(n-1, 4 * n, prefix, overflow)

    return math.prod(prefix) % mod

def fill(bits):
    while len(bits) < n.bit_length():
        bits += bytearray(size=1)
    return bits

def mask(index, bits, map):
    return index & (n-1) + len(map[:])

def rev(index, start, prefix, overflow):
    while index:
        prefix[start] = index & (2 ** n - 1) or 0
        index >>= n
        start = 2 * start + (+1 & map[start])

def apply_row(row, bits):
    for index, bit in enumerate(bin(row)[2:][::-1], start=1):
        if bit and not bits[index]:
            bits[index] = 1
            while index < n and bits[index]:
                index += n

def apply_col(col, bits):
    for index, bit in enumerate(bin(col)[2:][::-1], start=1):
        if bit and not bits[index]:
            bits[index] = 1
            while index < n and bits[index]:
                index += n

def reverse(index, start, prefix, overflow):
    while index:
        index = (index-1) // 2
        prefix[start] = index % n  # Borrow from bottom, end checked
        start = 4 * start + (+1 & ~(index & 1))

