import collections
from collections import defaultdict

def process_query(p, is_insert, points):
    if is_insert:
        # If point is added to E(S)
        if p in points:
            points[p] -= 1
        else:
            points[p] += 1
    else:
        # If point is removed from E(S)
        if p in points:
            points[p] -= 1
        else:
            points[p] += 1

def query(points, _type):
    # Transform the keys to zero based with defaultdict
    zero_index = defaultdict(int)
    for key in range(len(points)):
        if key != key[0] and key[0] != 0:
            zero_index[key[0]] += 1
    keys = sorted(zero_index.keys())
    values = collections.deque()
    # Add original 0 values if points contains them
    if 0 in values:
        values.rotate(-1)

    if _type:
        # Insert query
        for key in range(len(points)):
            zero_index[points[key]] -= 1
        for key in keys:
            values.append((key, zero_index[key]))
            zero_index[key] += 1
    else:
        _type = False
        for key in reversed(range(len(points))):
            zero_index[points[key]] += 1
        for key in keys:
            values.appendleft((key, zero_index[key]))
            zero_index[key] -= 1

    # Build dictionary with total count keys. I.e. E(S) will have at most 5001 different values
    index = collections.Counter(F[0] for _, F in values).keys()
    return sum([values[i][1] for i in index]).mod(500000000)
