from functools import lru_cache

def maximize_board_sum(rows, cols):
    if cols == 1:
        return sum(rows)
    also_odd = (rows % 2 == 1) and (cols % 2 == 1)
    if also_odd:
        return 2 * (max(rows) + max(cols))
    half_sum = sum(sum(row) for row in rows)
    half_cols = len(rows) // 2
    min_row = min(rows)
    max_row = max(rows) - min_row
    spliced_rand_vec_sum = (
        (-min_row) * min_row
        + (max_row - min_row) * half_cols * half_cols
        + sum((rows[i] + rows[cols[1:][-1-i]]) / 2 for i in range(half_cols))
        + sum((rows[cols[-1-i]] + rows[:cols[-1-i]]) / 2 for i in range(half_cols))
    )
    return max(half_sum - spliced_rand_vec_sum, half_sum + spliced_rand_vec_sum)

n = int(input().strip())
rows = [list(map(int, input().strip().split())) for _ in range(n)]

@lru_cache(None)
def dfs(bit, offset):
    opposite_bit = not bit
    if len(rows) == n**2:
        return maximize_board_sum(bit, opposite_bit)
    row, col = n - 1 - offset, n - 2 - offset
    arr = (row * [0] + row * [bit])[:-1]
    return max(-rows[row][col] + dfs(not bit, offset), dfs(not bit, offset + 1) - -rows[row][col])

